const e={title:"TripReel - Aplicativo Gratuito de Animação de Viagens: Transforme Fotos em Vídeos Bonitos",description:"Crie vídeos de viagem impressionantes com mapas animados e rotas de voo. Aplicativo gratuito de animação de viagens com mapeamento de rota de globo 3D. Transforme suas fotos em vídeos de viagem bonitos automaticamente. Privacidade em primeiro lugar, funciona offline.",keywords:"aplicativo de animação de viagens, aplicativo de animação de mapa de viagens, aplicativo de animação de rota de viagens, aplicativo de animação de voo, criador de vídeo de viagens, vídeo de viagem automático, mapa de viagem animado, animação de rota de voo, animação de viagem, animação de globo, vídeo de recapitulação de viagem, foto para vídeo, destaques de viagem, aplicativo de viagem gratuito, criador de vídeo offline, aplicativo de viagem privado, vídeo de rolo de câmera"},a={logoAlt:"Logo TripReel",appName:"TripReel",howItWorks:"Como funciona",video:"Vídeo",features:"Recursos",theApp:"O app"},o={badge:"Transforme fotos em histórias de viagem",title1:"Seu rolo de câmera,",title2:"totalmente aproveitado",description:"O TripReel cria automaticamente lindos vídeos de viagem a partir das localizações das suas fotos. Veja suas jornadas ganharem vida com mapas de rota animados e rotas de voo em um globo 3D, mantendo seus dados privados e seguros.",secure:"100% seguro",worksOffline:"Funciona offline",globeAlt:"Animação do globo TripReel"},s={title:"Como funciona",subtitle:"Três passos simples para criar seu vídeo de viagem perfeito",step1:{title:"Permitir acesso às fotos",description:"Conceda ao TripReel acesso à sua biblioteca de fotos. O app lê apenas metadados de localização, nada mais."},step2:{title:"Detecção automática de viagens",description:"O TripReel analisa metadados de localização e encontra inteligentemente suas viagens com base em datas e locais."},step3:{title:"Gere seu vídeo",description:"Assista sua jornada se desenrolar em uma linda animação do globo, pronta para compartilhar nas redes sociais."}},i={title:"Veja a mágica acontecer",subtitle:"Descubra como o TripReel transforma sua biblioteca de fotos em vídeos de viagem incríveis",caption:"É assim que seu vídeo de viagem final pode ficar"},t={title:"Tudo que você precisa",subtitle:"Recursos poderosos projetados para viajantes modernos",twoTap:{title:"Vídeos de viagem com dois toques",description:"Crie vídeos de viagem incríveis da sua biblioteca de fotos com apenas dois toques. Sem edição necessária."},smartTrip:{title:"Detecção inteligente de viagens",description:"Encontra e agrupa automaticamente suas viagens analisando datas e metadados de localização das suas fotos."},globe:{title:"Linda animação do globo",description:"Veja sua jornada ganhar vida com um impressionante globo 3D mostrando suas rotas de viagem animadas e rotas de voo ao redor do mundo."},privacy:{title:"Privacidade em primeiro lugar",description:"Tudo é processado no seu dispositivo. Suas fotos nunca saem do seu telefone. Funciona em modo avião."},customStyles:{title:"Estilos personalizados",description:"Escolha entre vários estilos de globo e personalizações para combinar com sua estética e tornar cada vídeo único."},manualControl:{title:"Controle manual",description:"Você pode adicionar manualmente viagens totalmente novas se os serviços de localização não estavam habilitados no seu dispositivo."}},r={title:"Ideias criativas de vídeos",subtitle:"Inspire-se com o que você pode criar usando o TripReel. De escapadas rápidas de fim de semana a aventuras de um ano, crie vídeos de viagem incríveis para cada jornada.",description:"Seja criando uma animação de mapa de viagem, documentando uma rota de voo ou fazendo um resumo anual de viagens, o TripReel facilita transformar suas memórias em vídeos compartilháveis.",ideas:{yearRecap:{title:"Resumo de viagens 2025",description:"Crie automaticamente seu vídeo de resumo anual de viagens de 2025"},europeRoadTrip:{title:"Road trip pela Europa",description:"Mostre sua aventura europeia com mapas de rota animados"},southeastAsia:{title:"Viagem pelo Sudeste Asiático",description:"Visualize sua rota de mochilão através de vários países"},japanRail:{title:"Viagem de trem pelo Japão",description:"Crie vídeos de mapas de suas rotas de trem pelo Japão"},crossCountry:{title:"De costa a costa nos EUA",description:"Transforme seu road trip americano em um vídeo de rota épico"},islandHopping:{title:"Salto entre ilhas",description:"Mostre suas viagens de ilha em ilha com impressionantes animações 3D"},worldTour:{title:"Montagem de volta ao mundo",description:"Várias viagens em um incrível vídeo de jornada global"},travelPlans:{title:"Planos de viagem 2026",description:"Visualize e planeje suas emocionantes aventuras de viagem para 2026"},lifetimeTravel:{title:"História de viagem de uma vida",description:"Crie um vídeo mostrando todas as suas viagens de toda uma vida"},regionalExplorer:{title:"Explorador regional",description:"Mapeie suas aventuras por estados, províncias e regiões"},festivalCircuit:{title:"Circuito de festivais",description:"Mapeie sua jornada por festivais de música e eventos"},bikeRoutes:{title:"Minhas escapadas urbanas",description:"Mostre todas as suas escapadas para a cidade"}}},d={title:"O app",subtitle:"Disponível agora na App Store",alt1:"Vídeos de viagem automáticos - Crie vídeos incríveis em segundos",alt2:"Detecção de localização de fotos - Usa os metadados das suas fotos",alt3:"Detecção de viagens - Agrupa automaticamente suas viagens",alt4:"Lindos vídeos do globo - Animação do globo da sua jornada",alt5:"Estilos personalizados - Personalize seus vídeos de viagem"},n={comingSoon:"Em breve",androidTitle:"App Android em breve!",androidMessage:'A versão Android ainda não está disponível, mas estará em breve. Envie uma mensagem para <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> e eu te aviso quando estiver pronto!',gotIt:"Entendi!"},m={title:"Perguntas frequentes",subtitle:"Tudo que você precisa saber sobre o TripReel",q1:{question:"Posso realmente usar o app totalmente em modo avião?",answer:"Sim! Para usuários premium, o app pode ser usado completamente offline em modo avião sem limitações. Para usuários não premium, alguns recursos são suportados por anúncios que podem exigir habilitar a internet temporariamente, mas para usuários premium não há anúncios e o app pode ser usado totalmente em modo avião."},q2:{question:"Fiz upgrade para Premium, como posso remover a marca d'água?",answer:"Muitas pessoas perguntam qual app foi usado para criar esses vídeos, então após o upgrade para premium, você tem a opção de adicionar uma versão menor da marca d'água (apenas com o nome do app) ou removê-la completamente se desejar."},q3:{question:"Os dados das minhas fotos estão seguros e privados?",answer:"Absolutamente! O TripReel lê apenas metadados de localização das suas fotos - nunca acessamos, armazenamos ou transmitimos o conteúdo real das fotos. Todo o processamento acontece localmente no seu dispositivo, e nenhum dado jamais sai do seu telefone. Você pode verificar isso usando o app em modo avião - funciona perfeitamente offline!"},q4:{question:"E se minhas fotos não tiverem dados de localização?",answer:"Sem problema! Se os serviços de localização não estavam habilitados quando você tirou suas fotos, você pode criar viagens manualmente e adicionar localizações você mesmo. O app te dá controle total para personalizar sua linha do tempo de viagens."},q5:{question:"Como o app detecta minhas viagens automaticamente?",answer:"O TripReel analisa os metadados de localização e carimbos de data/hora das suas fotos para identificar inteligentemente quando e onde você viajou. Ele agrupa localizações e datas próximas para detectar automaticamente suas viagens sem nenhum trabalho manual."},q6:{question:"Posso personalizar a aparência dos meus vídeos?",answer:"Sim! Você pode escolher entre vários estilos de globo e personalizar diversos aspectos dos seus vídeos de viagem animados para combinar com sua estética pessoal. Usuários premium obtêm acesso a estilos adicionais de animação de rota, temas de mapas e opções de rotas de voo."},q7:{question:"Preciso criar uma conta?",answer:"Nenhuma conta necessária! O TripReel funciona imediatamente após o download. Não há registro, não há login e nenhuma informação pessoal necessária. Apenas baixe o app e comece a criar seus vídeos de viagem imediatamente."},q8:{question:"Por que uma localização está faltando da minha viagem?",answer:"O app só pode trabalhar com dados disponíveis, então primeiro de tudo você precisa de pelo menos algumas fotos naquela localização. Segundo, você precisa ter certeza de que tinha dados de localização habilitados quando estava lá. Terceiro, às vezes recepção GPS fraca pode causar dados de localização incorretos. Se você descartou tudo isso e sua localização ainda não aparece, você pode adicionar manualmente aquela localização em Visão geral de viagens > botão Editar. Por favor, use também Contato para reportar o problema."},q9:{question:"Onde posso compartilhar meu vídeo incrível?",answer:"Claro, você também pode compartilhá-lo em todas as plataformas sociais. Para se adequar melhor à plataforma, o app permite diferentes proporções de aspecto para seus vídeos."},q10:{question:"Onde posso reportar um bug?",answer:"Apenas entre em contato diretamente em marian@qod.ee, explicando brevemente qual é o problema."}},l={title:"Suporte por email",description:"Se você tiver algum feedback ou encontrar algum problema, sinta-se à vontade para entrar em contato diretamente neste email e eu pessoalmente lerei e tratarei sua solicitação o mais rápido possível. Obrigado por usar o app!",close:"Fechar"},c={default:{title:"🍪 Cookies",message:"Usamos cookies no site TripReel para melhorar sua experiência. Nenhum dado pessoal coletado.",accept:"Aceitar",decline:"Recusar",details:"Detalhes"},theme:{title:"🍪 Cookies",message:"🌙 Para salvar sua preferência de tema, você precisa aceitar cookies essenciais no site TripReel. Sem eles, sua escolha de tema não pode ser salva.",accept:"Aceitar",decline:"Recusar",details:"Detalhes"}},p={privacy:"Política de privacidade do app",cookies:"Política de cookies do site",contact:"Contato",cookiePreferences:"Preferências de cookies",madeWith:"Feito com",forTravelers:"para viajantes do mundo todo",copyright:"© {{year}} TripReel."},u={title:"Pronto para compartilhar sua jornada?",description:"Baixe o TripReel hoje e transforme seu rolo de câmera em lindos vídeos de viagem com mapas e rotas animados. Suas aventuras merecem ser celebradas.",features:"Download gratuito • Rápido e conveniente • Privacidade garantida"},v={meta:e,header:a,hero:o,howItWorks:s,videoSection:i,features:t,videoIdeas:r,screenshots:d,appStore:n,faq:m,contact:l,cookieBanner:c,footer:p,cta:u};export{n as appStore,l as contact,c as cookieBanner,u as cta,v as default,m as faq,t as features,p as footer,a as header,o as hero,s as howItWorks,e as meta,d as screenshots,r as videoIdeas,i as videoSection};
